using System;using System.Drawing;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
partial class AvalonInterno {
 TextBox remountKey=new TextBox();Keys remountChoice=Keys.F7;bool remountCtrl,remountAlt,remountShift;
 string RemountKeyText(){return(remountCtrl?"Ctrl+":"")+(remountAlt?"Alt+":"")+(remountShift?"Shift+":"")+remountChoice;}
 void RemountKeyEditor(int x,int y){remountKey.SetBounds(x,y,58,16);remountKey.ReadOnly=true;remountKey.BorderStyle=BorderStyle.None;remountKey.Text=RemountKeyText();remountKey.TextAlign=HorizontalAlignment.Center;remountKey.BackColor=Color.Black;remountKey.ForeColor=Color.Cyan;remountKey.Font=new Font("Segoe UI",(float)(8)*global::UiScale.F);remountKey.KeyDown+=(o,e)=>{e.SuppressKeyPress=true;if(e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.Menu)return;remountChoice=e.KeyCode;remountCtrl=e.Control;remountAlt=e.Alt;remountShift=e.Shift;remountKey.Text=RemountKeyText();Save();};Controls.Add(remountKey);hints.SetToolTip(remountKey,"Clique e pressione a tecla para Remontar PT. Padrão: F7.");}
 void BindRemount(){remountKey.Text=RemountKeyText();Win.UnregisterHotKey(Handle,3);if(!shortcutActive||!gameInFront||controlLocked)return;uint mods=0x4000|(remountCtrl?2u:0u)|(remountAlt?1u:0u)|(remountShift?4u:0u);Note(Win.RegisterHotKey(Handle,3,mods,(uint)remountChoice)?"Remontar PT: atalho "+RemountKeyText():"Tecla de Remontar PT ocupada; escolha outra.");}
 void RemountButton(){var button=ButtonAt("Remontar PT",270,445,143,()=>{var task=RemountParty();});button.Height=29;hints.SetToolTip(button,"Transfere liderança temporariamente, encerra a PT anterior e reúne novamente os selecionados com o principal como líder.");}
 async Task RemountParty(){if(closeInProgress)return;CancelBuffWait();await YieldFollowRepair();if(busy||teleport.Working||missions.Working){Note("Aguarde a operação atual para remontar PT.");return;}var primary=main.SelectedItem as Entry;if(primary==null){Note("Escolha o principal.");return;}if(!ProcessAlive(primary.Pid)){Note(primary.Name+": cliente do jogo fechado. Clique Sincronizar personagens.");return;}foreach(var gone in followers.CheckedItems.Cast<Entry>().Where(e=>!ProcessAlive(e.Pid)))Note(gone.Name+": cliente do jogo fechado; fica fora da remontagem.");var selected=followers.CheckedItems.Cast<Entry>().Where(rz=>!RotaLock.Busy(rz.Pid)).Where(e=>e.Pid!=primary.Pid&&ProcessAlive(e.Pid)).ToArray();var remountOthers=main.Items.Cast<object>().OfType<Entry>().Where(e=>e.Pid!=primary.Pid&&!selected.Contains(e)&&!blocked.Contains(e.Pid)&&ProcessAlive(e.Pid)).Select(e=>e.Ref()).ToArray();if(selected.Length==0){Note("Selecione todos os secundários da PT antes de remontar.");return;}if(blocked.Contains(primary.Pid)||selected.Any(s=>blocked.Contains(s.Pid))){Note("Reinicie o cliente cuja ponte anterior não confirmou remoção.");return;}
  busy=true;action.Enabled=false;partyCancel=new CancellationTokenSource();var token=partyCancel.Token;var progress=new Progress<string>(s=>Note(s));try{await StopAttacks();var result=await Task.Run(()=>PartyService.Remount(primary.Ref(),selected.Select(s=>s.Ref()).ToArray(),token,(IProgress<string>)progress,remountOthers));if(result.Blocked)blocked.Add(result.Pid);Note(result.Message);status.Text=result.Message;}
  catch(Exception e){Note("Remontar PT: "+e.Message);}finally{partyCancel.Dispose();partyCancel=null;busy=false;action.Enabled=true;}
 }
}
